namespace PZ3D {
 // Legacy automatic-binding compatibility tests intentionally exercise the bound legacy adapter.
 // Unified selected-configuration dispatch is covered by OwnedLaunchIntegrationTests.
 static class SaveEnvironmentControllerTests {
  static int checks;static readonly JavaScriptSerializer Json=new JavaScriptSerializer{MaxJsonLength=4194304};
  static void Check(bool value,string message){if(!value)throw new Exception("FAIL "+message);checks++;}
  static void Put(string file,string text){Directory.CreateDirectory(Path.GetDirectoryName(file));File.WriteAllText(file,text,new UTF8Encoding(false));}
  static Dictionary<string,object> P(params string[] values){var result=new Dictionary<string,object>();for(int i=0;i<values.Length;i+=2)result.Add(values[i],values[i+1]);return result;}
  static object Invoke(string method,object target,params object[] values){var members=typeof(ModernController).GetMethods(BindingFlags.Instance|BindingFlags.Static|BindingFlags.Public|BindingFlags.NonPublic).Where(m=>m.Name==method&&m.GetParameters().Length==values.Length).ToArray();Check(members.Length==1,"environment controller API exists: "+method);try{return members[0].Invoke(target,values);}catch(TargetInvocationException error){throw error.InnerException;}}
  static Dictionary<string,object> D(object value){return Json.Deserialize<Dictionary<string,object>>(Json.Serialize(value));}
  static Dictionary<string,object> Dispatch(ModernController c,string action,Dictionary<string,object> payload){return D(Invoke("DispatchEnvironment",c,action,payload));}
  static void Refuses(Action action,string message){bool failed=false;try{action();}catch(Exception){failed=true;}Check(failed,message);}
  static void Validate(string action,Dictionary<string,object> payload,bool web=false){Invoke("ValidateEnvironmentPayload",null,action,payload,web);}
  static Dictionary<string,object>[] Rows(Dictionary<string,object> value,string name){return ((IEnumerable)value[name]).Cast<Dictionary<string,object>>().ToArray();}
  static void Payloads(){string stamp=new string('a',64),id=new string('1',32);
   Check((bool)Invoke("EnvironmentAction",null,"environmentCreateDefault")&&(bool)Invoke("EnvironmentWebAction",null,"environmentCreateDefault"),"default path creation has a web action without exposing a raw destination");Validate("environmentStorageGet",P(),true);Validate("environmentStorageChoose",P(),true);Validate("environmentCreateDefault",P("saveId","Sandbox/Alpha","name","Snapshot","stamp",stamp),true);
   Check((bool)Invoke("EnvironmentAction",null,"environmentCreate")&&!(bool)Invoke("EnvironmentAction",null,"notAnAction"),"native action admission is exact");Check(!(bool)Invoke("EnvironmentWebAction",null,"environmentCreate")&&(bool)Invoke("EnvironmentWebAction",null,"environmentChooseCreate"),"web admission permits native chooser alias and rejects raw create");
   Validate("environmentList",P(),true);Validate("environmentList",P("saveId","Sandbox/Alpha"),true);Validate("environmentPreview",P("saveId","Sandbox/Alpha"),true);Validate("environmentPreview",P("saveId","Sandbox/Alpha","jobId",id),true);Validate("environmentPreviewCancel",P("jobId",id),true);Refuses(()=>Validate("environmentPreviewCancel",P(),true),"preview cancellation requires its exact owned job");Refuses(()=>Validate("environmentPreview",P("saveId","Sandbox/Alpha","jobId","../wrong"),true),"invalid preview job cannot select a different operation");Validate("environmentChooseCreate",P("saveId","Sandbox/Alpha","name","","stamp",stamp),true);Validate("environmentCreate",P("saveId","Sandbox/Alpha","name","Snapshot","stamp",stamp,"destination",Path.Combine(Path.GetTempPath(),"unused-controller-destination")));
   Refuses(()=>Validate("environmentCreate",P("saveId","Sandbox/Alpha","name","Snapshot","stamp",stamp,"destination","C:/outside"),true),"web cannot submit raw snapshot destination");Refuses(()=>Validate("environmentChooseCreate",P("saveId","Sandbox/Alpha","name","Snapshot","stamp",stamp,"destination","C:/outside"),true),"chooser alias rejects injected destination");
   Refuses(()=>Validate("environmentBind",P("saveId","Sandbox/Alpha","snapshotId",id,"stamp","stale"),true),"invalid stamp format is rejected before storage");Refuses(()=>Validate("environmentBind",P("saveId","Sandbox/Alpha","snapshotId","../escape","stamp",stamp),true),"invalid snapshot identity cannot become a path");Refuses(()=>Validate("environmentPreview",P("saveId","Multiplayer/Cache"),true),"snapshot actions target singleplayer saves only");Refuses(()=>Validate("environmentPreview",P("saveId","../escape"),true),"save ID cannot escape original user root");Refuses(()=>Validate("environmentCheck",new Dictionary<string,object>{{"snapshotId",23}},true),"typed snapshot identifiers must be strings");Refuses(()=>Validate("environmentList",P("unrelated","value"),true),"unknown list keys are rejected");Refuses(()=>Validate("environmentUnbind",P("saveId","Sandbox/Alpha","stamp",stamp,"confirmed","true"),true),"unrelated confirmation fields cannot bypass action shape");Refuses(()=>Validate("environmentChooseCreate",P("saveId","Sandbox/Alpha","name",new string('n',101),"stamp",stamp),true),"overlong names are rejected");
  }
  sealed class Fixture:IDisposable {
   internal readonly string Root,Game,User,Data,Save;internal readonly ModernController Controller;internal readonly Engine Engine;
   internal Fixture(string parent,string name,Func<Engine,string,Dictionary<string,object>,Action<int,string>,CancellationToken,Action<object>,object> network=null){Root=Path.Combine(parent,name);Game=Path.Combine(Root,"steamapps","common","ProjectZomboid");User=Path.Combine(Root,"user");Data=Path.Combine(Root,"data");Save=Path.Combine(User,"Saves","Sandbox","Alpha");Put(Path.Combine(Game,"ProjectZomboid64.exe"),"fixture game");Put(Path.Combine(Game,"ProjectZomboid64.json"),"{\"vmArgs\":[]}");Put(Path.Combine(Game,"version.txt"),"42.21.0");Put(Path.Combine(Game,"game-version.txt"),"42.21.0");Put(Path.Combine(Game,"media","game.bin"),"original source");Put(Path.Combine(User,"mods","Example","42","mod.info"),"id=Example\nname=Example\n");Put(Path.Combine(User,"mods","Example","common","media","file.bin"),"mod source");string mods="mods\n{\n mod = Example,\n}\nmaps\n{\n}\n";Put(Path.Combine(User,"mods","default.txt"),mods);Put(Path.Combine(Save,"mods.txt"),mods);Put(Path.Combine(Save,"map.bin"),"live save");Put(Path.Combine(User,"Saves","Sandbox","Beta","mods.txt"),mods);Put(Path.Combine(User,"Saves","Multiplayer","Online","mods.txt"),mods);Controller=new ModernController(Game,User,Data,true,null,network,null,null,true);Engine=(Engine)typeof(ModernController).GetField("engine",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(Controller);}
   internal Dictionary<string,object> Preview(){return Dispatch(Controller,"environmentPreview",P("saveId","Sandbox/Alpha"));}
   internal Dictionary<string,object> Create(string folder){var plan=Preview();return Dispatch(Controller,"environmentCreate",P("saveId","Sandbox/Alpha","destination",Path.Combine(Root,folder),"name","Snapshot "+folder,"stamp",(string)plan["stamp"]));}
   public void Dispose(){Controller.Dispose();}
  }
  static void SourceRecoveryDoesNotBlockCopy(string root){string target=Path.Combine(Path.GetTempPath(),"ozl-snapshot-recovery-copy-"+Guid.NewGuid().ToString("N"));try{using(var f=new Fixture(root,"p")){
   Put(PlayProfileTransaction.Journal(f.Engine),"fixture pending source configuration; never read or modified by copy");var saved=D(f.Controller.Execute("environmentStorageSave",P("directory",target)));Check((string)saved["directory"]==target,"unrelated source recovery does not block remembering the next snapshot directory");byte[] before=File.ReadAllBytes(PlayProfileTransaction.Journal(f.Engine));var plan=f.Preview();var result=D(f.Controller.Execute("environmentCreateDefault",P("saveId","Sandbox/Alpha","name","Copy source without applying recovery","stamp",(string)plan["stamp"])));var snapshot=(Dictionary<string,object>)result["snapshot"];Check(Directory.Exists(Path.Combine((string)snapshot["rootPath"],"game"))&&new SaveEnvironments(f.Engine).Bound("Sandbox/Alpha")!=null,"source recovery record does not block copying into an independent snapshot");Check(before.SequenceEqual(File.ReadAllBytes(PlayProfileTransaction.Journal(f.Engine))),"copy leaves the source recovery record byte-identical");
  }}finally{if(!Path.GetFileName(target).StartsWith("ozl-snapshot-recovery-copy-",StringComparison.Ordinal)||Path.GetDirectoryName(target)!=Path.GetFullPath(Path.GetTempPath()).TrimEnd(Path.DirectorySeparatorChar))throw new IOException("Unsafe recovery-copy fixture cleanup");if(Directory.Exists(target))Directory.Delete(target,true);}}
  static void CompactListAndReversibleBindings(string root){SourceRecoveryDoesNotBlockCopy(root);DefaultDirectoryCreatesWithoutPicker(root);using(var f=new Fixture(root,"compact")){
   var empty=Dispatch(f.Controller,"environmentList",P());Check((string)empty["selectedSaveId"]=="Sandbox/Alpha"&&(string)empty["selectedSaveName"]=="Alpha"&&Rows(empty,"saves").Length==2&&Rows(empty,"snapshots").Length==0,"list selects first editable save and excludes multiplayer caches");Check((bool)empty["saveBackupSeparate"],"UI distinguishes game/mod snapshot from separate save backups");var beta=Dispatch(f.Controller,"environmentList",P("saveId","Sandbox/Beta"));Check((string)beta["selectedSaveName"]=="Beta","explicit save selection is honored");Refuses(()=>Dispatch(f.Controller,"environmentList",P("saveId","Sandbox/Missing")),"unknown save selection is not silently rebound");
   byte[] before=File.ReadAllBytes(Path.Combine(f.Save,"map.bin"));var result=f.Create("one");var list=(Dictionary<string,object>)result["list"];var snapshot=(Dictionary<string,object>)result["snapshot"];string id=(string)snapshot["id"];Check((string)list["activeSnapshotId"]==id&&Rows(list,"snapshots").Single()["active"].Equals(true),"creation returns compact refreshed active binding");Check((int)snapshot["modCount"]==1&&(long)Convert.ToInt64(snapshot["bytes"])>0&&(string)snapshot["gameVersion"]=="42.21.0","summary exposes version mod count and disk bytes");string serialized=Json.Serialize(result);Check(!new[]{"ApprovalBytes","SourceFiles","GameSourceFiles","ManifestHash","DefaultBytes","PreloadJars","\"Files\""}.Any(serialized.Contains)&&serialized.Length<12000,"UI DTO does not serialize approval payloads manifests or file arrays");Check(before.SequenceEqual(File.ReadAllBytes(Path.Combine(f.Save,"map.bin")))&&!Directory.Exists(Path.Combine(f.Data,"save-backups")),"creation leaves live save bytes unchanged and creates no save archive");
   var unbound=Dispatch(f.Controller,"environmentUnbind",P("saveId","Sandbox/Alpha","stamp",(string)list["stamp"]));var off=(Dictionary<string,object>)unbound["list"];Check((string)off["activeSnapshotId"]==""&&Rows(off,"snapshots").Length==1,"use current environment removes only binding and retains history");Refuses(()=>Dispatch(f.Controller,"environmentBind",P("saveId","Sandbox/Alpha","snapshotId",id,"stamp",(string)list["stamp"])),"stale UI stamp cannot override a later unbind");var rebound=Dispatch(f.Controller,"environmentBind",P("saveId","Sandbox/Alpha","snapshotId",id,"stamp",(string)off["stamp"]));Check((string)((Dictionary<string,object>)rebound["list"])["activeSnapshotId"]==id,"retained snapshot can be selected again without extra save writes");Check(object.ReferenceEquals(f.Engine,typeof(ModernController).GetField("engine",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(f.Controller)),"snapshot operations keep main selected Engine unchanged");
   var check=Dispatch(f.Controller,"environmentCheck",P("snapshotId",id));Check((bool)check["available"]&&!(bool)check["changed"],"explicit source check returns unchanged for exact original bytes");Directory.Delete(f.Game,true);var sourceGone=Dispatch(f.Controller,"environmentList",P("saveId","Sandbox/Alpha"));Check((string)sourceGone["activeSnapshotId"]==id&&Rows(sourceGone,"snapshots").Length==1,"list reads registered snapshots after source game deletion");
  }}
  static void DefaultDirectoryCreatesWithoutPicker(string root){string target=Path.Combine(Path.GetTempPath(),"ozl-snapshot-default-"+Guid.NewGuid().ToString("N"));try{using(var f=new Fixture(root,"default-location")){
   var saved=Dispatch(f.Controller,"environmentStorageSave",P("directory",target));Check((string)saved["directory"]==target&&(string)Dispatch(f.Controller,"environmentStorageGet",P())["directory"]==target,"explicit directory selection persists and is returned for the next snapshot");Check(!Directory.Exists(target),"saving a preference does not create an empty snapshot directory");var plan=f.Preview();var result=Dispatch(f.Controller,"environmentCreateDefault",P("saveId","Sandbox/Alpha","name","Default folder snapshot","stamp",(string)plan["stamp"]));var row=(Dictionary<string,object>)result["snapshot"];Check(Path.GetDirectoryName((string)row["rootPath"])==target&&Directory.Exists((string)row["rootPath"]),"default create performs a real snapshot copy below the remembered directory without a picker payload");
  }}finally{if(!Path.GetFileName(target).StartsWith("ozl-snapshot-default-",StringComparison.Ordinal)||Path.GetDirectoryName(target)!=Path.GetFullPath(Path.GetTempPath()).TrimEnd(Path.DirectorySeparatorChar))throw new IOException("Unsafe default fixture cleanup");if(Directory.Exists(target))Directory.Delete(target,true);}}
  static void FailedCreationKeepsPriorBinding(string root){using(var f=new Fixture(root,"failure")){
   var first=f.Create("prior");var list=(Dictionary<string,object>)first["list"];string previous=(string)list["activeSnapshotId"];bool changed=false;f.Controller.Progress=(value,text)=>{if(!changed&&text.StartsWith("复制游戏",StringComparison.Ordinal)){changed=true;Put(Path.Combine(f.Game,"late-source-change.bin"),"Steam update");}};Refuses(()=>f.Create("failed"),"controller propagates genuine storage source-mutation failure");var after=Dispatch(f.Controller,"environmentList",P("saveId","Sandbox/Alpha"));Check(changed&&(string)after["activeSnapshotId"]==previous&&Rows(after,"snapshots").Length==1&&!Directory.Exists(Path.Combine(f.Root,"failed")),"failed creation preserves prior working binding and removes only owned new copy");
   var cancel=(CancellationTokenSource)typeof(ModernController).GetField("cancel",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(f.Controller);cancel.Cancel();Refuses(()=>Dispatch(f.Controller,"environmentPreview",P("saveId","Sandbox/Alpha")),"controller preview honors cancellation");Refuses(()=>Dispatch(f.Controller,"environmentCheck",P("snapshotId",previous)),"controller explicit hash check honors cancellation");
  }}
  static void CancellationAfterCommitReportsSuccess(string root){using(var f=new Fixture(root,"committed")){
   var cancellation=(CancellationTokenSource)typeof(ModernController).GetField("cancel",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(f.Controller);f.Controller.Progress=(value,text)=>{if(value==100)cancellation.Cancel();};var result=f.Create("one");string id=(string)((Dictionary<string,object>)result["snapshot"])["id"];Check(cancellation.IsCancellationRequested&&new SaveEnvironments(f.Engine).Bound("Sandbox/Alpha").Id==id&&result.ContainsKey("list"),"cancellation after atomic commit does not misreport a committed binding as failed");
  }}
  static void MissingWorkshopSourcesPrepareThenCreate(string root){var downloaded=new List<string>();using(var f=new Fixture(root,"auto-prepare",(engine,action,payload,progress,token,batch)=>{
   Check(action=="download"&&payload["id"] is string&&payload["confirmed"].Equals(true),"snapshot uses the authorized exact Workshop download action");string id=(string)payload["id"];downloaded.Add(id);string mod=id=="3809306528"?"Viewpoint":id=="3619862853"?"ZombieBuddy":null;if(mod==null)throw new Exception("Unexpected fixture Workshop ID");Put(Path.Combine(engine.Workshop,id,"mods",mod,"42","mod.info"),"id="+mod+"\nname=Fixture "+mod+"\n"+(mod=="Viewpoint"?"require=ZombieBuddy\n":""));progress(100,"fixture verified");return new{id=id};
  })){
   Put(Path.Combine(f.Save,"mods.txt"),"mods\n{\n mod = Viewpoint,\n mod = Example,\n}\nmaps\n{\n}\n");byte[] save=File.ReadAllBytes(Path.Combine(f.Save,"mods.txt")),defaults=File.ReadAllBytes(f.Engine.Mods);var plan=f.Preview();Check(!(bool)plan["ready"]&&(bool)plan["canPrepare"],"missing known Workshop source offers automatic preparation");var result=f.Create("automatic");var snapshot=(Dictionary<string,object>)result["snapshot"];Check(downloaded.SequenceEqual(new[]{"3809306528","3619862853"}),"downloaded metadata is rescanned and its newly discovered dependency is prepared recursively");var stored=new SaveEnvironments(f.Engine).Get((string)snapshot["id"]);Check(stored.ModRoots.SelectMany(row=>row.ModIds).Contains("ZombieBuddy")&&stored.ModRoots.Length==3,"completed snapshot contains every requested source and recursive dependency");Check((int)snapshot["modCount"]==3,"summary counts implicitly loaded frozen dependencies");var frozen=new Engine(stored.GamePath,f.User,f.Data,true);var readBudget=new LaunchReadBudget(save.Length);SaveProfiles.LaunchMods(frozen,"Sandbox/Alpha",readBudget);Check(!readBudget.Incomplete,"reading a frozen save mod list does not rescan or consume the separate catalog budget");var launchCheck=LaunchPreflight.CheckLaunch(frozen,false,false,"save","Sandbox/Alpha",true);Check(launchCheck.items.Single(row=>row.id=="mods").status!="error","snapshot launch preflight uses the same recursive require closure as the game");Check(save.SequenceEqual(File.ReadAllBytes(Path.Combine(f.Save,"mods.txt")))&&defaults.SequenceEqual(File.ReadAllBytes(f.Engine.Mods)),"automatic dependency repair never rewrites original save or defaults");
  }}
  static void FailedOrCancelledPreparationKeepsBinding(string root){foreach(bool cancelled in new[]{false,true}){int attempts=0;using(var f=new Fixture(root,cancelled?"cancel-download":"wrong-variant",(engine,action,payload,progress,token,batch)=>{attempts++;if(cancelled)throw new OperationCanceledException(token);Put(Path.Combine(engine.Workshop,"3809306528","mods","WrongVariant","42","mod.info"),"id=OtherSubMod\n");return new{id="3809306528"};})){
   var original=f.Create("prior");string previous=(string)((Dictionary<string,object>)original["snapshot"])["id"];Put(Path.Combine(f.Save,"mods.txt"),"mods\n{\n mod = Viewpoint,\n mod = Example,\n}\nmaps\n{\n}\n");byte[] before=File.ReadAllBytes(Path.Combine(f.Save,"mods.txt"));Exception failure=null;try{f.Create("failed");}catch(Exception error){failure=error;}Check(failure!=null&&(cancelled?failure is OperationCanceledException:failure.Message.Contains("Viewpoint")&&failure.Message.Contains("子模组")),"preparation reports exact missing variant or cancellation");Check(attempts==1,"a downloaded item that lacks the required child is not retried indefinitely");var library=new SaveEnvironments(f.Engine);Check(library.Bound("Sandbox/Alpha").Id==previous&&library.List().Count==1&&!Directory.Exists(Path.Combine(f.Root,"failed")),"failed automatic preparation preserves prior binding and creates no partial snapshot");Check(before.SequenceEqual(File.ReadAllBytes(Path.Combine(f.Save,"mods.txt"))),"failed automatic preparation preserves original save config bytes");
  }}}
  static void ConcurrentBindingChangeDuringDownload(string root){foreach(bool sameSave in new[]{true,false})using(var f=new Fixture(root,sameSave?"same":"other",(engine,action,payload,progress,token,batch)=>{var library=new SaveEnvironments(engine);string selected=sameSave?"Sandbox/Alpha":"Sandbox/Beta";library.Unbind(selected,library.BindingStamp(selected));Put(Path.Combine(engine.Workshop,"3809306528","mods","Viewpoint","42","mod.info"),"id=Viewpoint\n");return new{id="3809306528"};})){
   var prior=f.Create("a");string previous=(string)((Dictionary<string,object>)prior["snapshot"])["id"];var betaPlan=Dispatch(f.Controller,"environmentPreview",P("saveId","Sandbox/Beta"));Dispatch(f.Controller,"environmentCreate",P("saveId","Sandbox/Beta","destination",Path.Combine(f.Root,"b"),"name","Beta","stamp",(string)betaPlan["stamp"]));Put(Path.Combine(f.Save,"mods.txt"),"mods\n{\n mod = Viewpoint,\n mod = Example,\n}\nmaps\n{\n}\n");Exception failure=null;Dictionary<string,object> result=null;try{result=f.Create("c");}catch(Exception error){failure=error;}var snapshots=new SaveEnvironments(f.Engine);
   if(sameSave)Check(failure!=null&&failure.Message.Contains("绑定")&&snapshots.Bound("Sandbox/Alpha")==null&&snapshots.List("Sandbox/Alpha").Count==1&&!Directory.Exists(Path.Combine(f.Root,"c")),"same-save selection changed during download is retained and never overwritten by automatic creation");else Check(failure==null&&result!=null&&snapshots.Bound("Sandbox/Alpha").Id!=previous&&snapshots.Bound("Sandbox/Beta")==null,"another save binding change does not block the prepared snapshot or get overwritten");
  }}
  static void CreationPublishesMeasuredPhaseEvents(string root){using(var f=new Fixture(root,"events")){
   var events=new List<Dictionary<string,object>>();bool committed=false;f.Controller.Event=(name,value)=>{if(name!="environmentProgress")return;var row=D(value);events.Add(row);if((string)row["stage"]=="complete")committed=new SaveEnvironments(f.Engine).Bound("Sandbox/Alpha")!=null;};f.Create("one");foreach(string stage in new[]{"copy-game","copy-mods","verify-copy","complete"})Check(events.Any(row=>(string)row["stage"]==stage),"controller forwards the actual creation phase: "+stage);Check(events.Where(row=>((string)row["stage"]).StartsWith("copy-",StringComparison.Ordinal)).All(row=>(string)row["saveId"]=="Sandbox/Alpha"&&row["jobId"]==null&&Convert.ToInt64(row["totalFiles"])>0&&Convert.ToInt64(row["totalBytes"])>0),"copy event includes save ownership and real file and byte denominators");Check(committed&&(string)events.Last()["stage"]=="complete","the controller announces completion only after its snapshot binding exists");
  }}
  static void IndependentVersionUsesRealSteamDownloadContext(string root){
   foreach(bool shaped in new[]{false,true}){
   string steamGame=null,independent=null;int calls=0;
   using(var f=new Fixture(root,shaped?"ind-shape":"ind-dl",(downloadEngine,action,payload,progress,token,batch)=>{
    Check(downloadEngine.Game==steamGame&&downloadEngine.Game!=independent,"independent-version snapshot downloads through the original Steam installation context");calls++;string id=(string)payload["id"];Check(id=="3809306528","independent version requests only the missing exact Workshop item");Put(Path.Combine(downloadEngine.Workshop,id,"mods","Viewpoint","42","mod.info"),"id=Viewpoint\nname=Viewpoint fixture\n");progress(100,"fixture installed in registered Steam library");return new{id=id};
   })){
    steamGame=f.Game;independent=shaped?Path.Combine(f.Root,"b","steamapps","common","ProjectZomboid"):Path.Combine(f.Root,"ind");Put(Path.Combine(independent,"ProjectZomboid64.exe"),"independent fixture game");Put(Path.Combine(independent,"ProjectZomboid64.json"),"{\"vmArgs\":[]}");Put(Path.Combine(independent,"version.txt"),"42.21.0");Put(Path.Combine(independent,"media","selected.bin"),"selected independent version");Invoke("SetEngine",f.Controller,independent,f.User,false);
    Put(Path.Combine(f.Save,"mods.txt"),"mods\n{\n mod = Viewpoint,\n mod = Example,\n}\nmaps\n{\n}\n");byte[] original=File.ReadAllBytes(Path.Combine(f.Save,"mods.txt"));var result=f.Create("i");var row=new SaveEnvironments(new Engine(independent,f.User,f.Data,true)).Get((string)((Dictionary<string,object>)result["snapshot"])["id"]);
    Check(calls==1&&row.SourceGame==independent&&File.ReadAllText(Path.Combine(row.GamePath,"media","selected.bin"))=="selected independent version","snapshot continues to copy selected independent game rather than the Steam download context");Check(row.ModRoots.Any(mod=>mod.ModIds.Contains("Viewpoint")&&mod.SourceRoot.StartsWith(f.Engine.Workshop,StringComparison.OrdinalIgnoreCase)),"verified Steam download is rediscovered outside independent game's derived Workshop path");Check(original.SequenceEqual(File.ReadAllBytes(Path.Combine(f.Save,"mods.txt"))),"independent-version automatic preparation preserves original save mod bytes");
   }
  }
  }
  public static int Main(){string root=null;try{Payloads();root=Path.Combine(LauncherTestPaths.Root,"environment-controller-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);IndependentVersionUsesRealSteamDownloadContext(root);CreationPublishesMeasuredPhaseEvents(root);ConcurrentBindingChangeDuringDownload(root);FailedOrCancelledPreparationKeepsBinding(root);MissingWorkshopSourcesPrepareThenCreate(root);CompactListAndReversibleBindings(root);FailedCreationKeepsPriorBinding(root);CancellationAfterCommitReportsSuccess(root);Console.WriteLine("SaveEnvironmentController PASS: "+checks+" assertions");return 0;}catch(Exception error){Console.WriteLine(error);return 1;}finally{if(root!=null){string path=Path.GetFullPath(root),parent=Path.GetFullPath(LauncherTestPaths.Root)+Path.DirectorySeparatorChar;if(!path.StartsWith(parent,StringComparison.OrdinalIgnoreCase)||!Path.GetFileName(path).StartsWith("environment-controller-",StringComparison.Ordinal))throw new IOException("Unsafe fixture cleanup");if(Directory.Exists(path))Directory.Delete(path,true);}}}
 }
}
